import { CheckIcon, ChevronRightIcon, CircleIcon } from "lucide-react"
import { Menu } from "@kitora/primitives/react"

const POPUP = "z-50 min-w-48 rounded-lg bg-popover p-1 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-none"
const ITEM = "flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 outline-none select-none data-disabled:opacity-50 data-highlighted:bg-accent data-highlighted:text-accent-foreground data-popup-open:bg-accent"

/** The popup of a menu or submenu: a portal, a positioner placing it, and the popup itself. */
function Popup({ children, side, sideOffset }: { children: ReactNode; side?: "bottom" | "inline-end"; sideOffset?: number }) {
  return (
    <Menu.Portal>
      <Menu.Positioner side={side} align="start" sideOffset={sideOffset} className="isolate z-50 outline-none">
        <Menu.Popup className={POPUP}>{children}</Menu.Popup>
      </Menu.Positioner>
    </Menu.Portal>
  )
}

/** A dropdown menu built from the primitives' \`Menu\` parts only: items, a label, a checkbox item, a radio group and a submenu. */
export function DropdownMenuBuildYourOwn({ open, onOpenChange }: { open?: boolean; onOpenChange?: (open: boolean) => void }) {
  const [grid, setGrid] = useState(true)
  const [density, setDensity] = useState("comfortable")
  const shareHint = useId()
  return (
    <Menu.Root open={open} onOpenChange={(next) => onOpenChange?.(next)}>
      <Menu.Trigger className="rounded-sm border border-border px-3 py-1.5 text-sm data-popup-open:bg-muted">Options</Menu.Trigger>
      <Popup side="bottom" sideOffset={4}>
        <Menu.Group>
          <Menu.GroupLabel className="px-2 py-1 text-xs font-medium text-muted-foreground">Document</Menu.GroupLabel>
          <Menu.Item className={ITEM}>
            Rename <span className="ms-auto text-xs text-muted-foreground">F2</span>
          </Menu.Item>
          <Menu.Item className={ITEM} aria-describedby={shareHint}>
            <div className="flex flex-col">
              Share
              <span id={shareHint} className="text-xs text-muted-foreground">Anyone with the link can view.</span>
            </div>
          </Menu.Item>
          <Menu.Item className={ITEM} disabled>
            Archive
          </Menu.Item>
        </Menu.Group>
        <Menu.Separator className="-mx-1 my-1 h-px bg-border" />
        <Menu.CheckboxItem className={ITEM} checked={grid} onCheckedChange={setGrid}>
          <span className="flex size-4 items-center justify-center">
            <Menu.CheckboxItemIndicator>
              <CheckIcon className="size-4" />
            </Menu.CheckboxItemIndicator>
          </span>
          Show grid
        </Menu.CheckboxItem>
        <Menu.RadioGroup value={density} onValueChange={(next) => setDensity(next as string)}>
          {["compact", "comfortable"].map((value) => (
            <Menu.RadioItem key={value} value={value} className={ITEM}>
              <span className="flex size-4 items-center justify-center">
                <Menu.RadioItemIndicator>
                  <CircleIcon className="size-2 fill-current" />
                </Menu.RadioItemIndicator>
              </span>
              {value === "compact" ? "Compact" : "Comfortable"}
            </Menu.RadioItem>
          ))}
        </Menu.RadioGroup>
        <Menu.Separator className="-mx-1 my-1 h-px bg-border" />
        <Menu.SubmenuRoot>
          <Menu.SubmenuTrigger className={ITEM}>
            Move to
            <ChevronRightIcon className="ms-auto size-4 rtl:rotate-180" />
          </Menu.SubmenuTrigger>
          <Popup side="inline-end">
            <Menu.Item className={ITEM}>Inbox</Menu.Item>
            <Menu.Item className={ITEM}>Archive folder</Menu.Item>
          </Popup>
        </Menu.SubmenuRoot>
      </Popup>
    </Menu.Root>
  )
}
